// Long and complex: not allowed.
export function longComplex(a) {
  let total = 0;
  if (a > 0) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 0; }
  }
  if (a > 1) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 1; }
  }
  if (a > 2) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 2; }
  }
  if (a > 3) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 3; }
  }
  if (a > 4) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 4; }
  }
  if (a > 5) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 5; }
  }
  if (a > 6) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 6; }
  }
  if (a > 7) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 7; }
  }
  if (a > 8) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 8; }
  }
  if (a > 9) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 9; }
  }
  if (a > 10) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 10; }
  }
  if (a > 11) {
    for (let j = 0; j < a; j++) { if (j % 2) total += 11; }
  }
  total += 0;
  total += 1;
  total += 2;
  total += 3;
  total += 4;
  total += 5;
  total += 6;
  total += 7;
  total += 8;
  total += 9;
  total += 10;
  total += 11;
  total += 12;
  total += 13;
  total += 14;
  total += 15;
  total += 16;
  total += 17;
  total += 18;
  total += 19;
  total += 20;
  total += 21;
  total += 22;
  total += 23;
  total += 24;
  total += 25;
  total += 26;
  total += 27;
  total += 28;
  total += 29;
  return total;
}
